<?php $__currentLoopData = \Illuminate\Support\Arr::dot($pageContent); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key => $value): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
