<label>Title<input name="title" value="<?php echo e(old('title',$editing?$page->title:'')); ?>" required></label><label>Slug<input name="slug" value="<?php echo e(old('slug',$editing?$page->slug:'')); ?>"></label><label>Body<input type="hidden" name="content[blocks][0][type]" value="<?php echo e(data_get($pageContent, 'blocks.0.type', 'paragraph')); ?>"><textarea id="page-body" name="content[blocks][0][data][text]" rows="18"><?php echo e(old('content.blocks.0.data.text', data_get($editing ? $page->content : [], 'blocks.0.data.text', ''))); ?></textarea></label><label>Status<select name="status"><option value="draft" <?php if(old('status',$editing?$page->status:'draft')==='draft'): echo 'selected'; endif; ?>>Draft</option><option value="published" <?php if(old('status',$editing?$page->status:'draft')==='published'): echo 'selected'; endif; ?>>Published</option></select></label><label>SEO Title<input name="seo_title" value="<?php echo e(old('seo_title',$editing?$page->seo_title:'')); ?>"></label><label>SEO Description<textarea name="seo_description"><?php echo e(old('seo_description',$editing?$page->seo_description:'')); ?></textarea></label><button class="inline-flex h-11 cursor-pointer items-center justify-center gap-2 rounded-md border border-transparent px-3.5 text-sm font-medium no-underline transition bg-[#526A5A] text-white hover:bg-[#293C32]">Save Page</button></form><?php /**PATH /Users/ferdy/project-fl/vet-cms/backend/resources/views/admin/pages/_form.blade.php ENDPATH**/ ?>